import {staticCollider,controlledCapsule,create3DEffects} from '../3d/index.js';
import {HARBORS} from './cloudwake-core.js';
// Original authored lofted aircraft, islands and harbor props; no downloaded assets.
export function createCloudScene(r,game,{getPresentation=()=>({})}={}){const {B,scene}=r,materials=new Map(),staticMeshes=[],pilots=[],rings=[],storms=[],proxies=[];scene.clearColor=new B.Color4(.075,.14,.23,1);scene.fogMode=B.Scene.FOGMODE_EXP2;scene.fogDensity=.011;scene.fogColor=new B.Color3(.09,.18,.28);const mat=(color,glow=0)=>{const key=color+glow;if(materials.has(key))return materials.get(key);const m=new B.StandardMaterial('cloud-'+key,scene);m.diffuseColor=B.Color3.FromHexString(color);m.emissiveColor=m.diffuseColor.scale(glow);m.specularColor=new B.Color3(.15,.19,.22);if(!r.software&&typeof document!=='undefined'&&['#e5cf9f','#b59b78','#648a7c'].includes(color)){const texture=new B.DynamicTexture('original-surface-'+key,{width:128,height:128},scene,false),ctx=texture.getContext();ctx.fillStyle=color;ctx.fillRect(0,0,128,128);ctx.strokeStyle=color==='#648a7c'?'#416f6477':'#6b5a4266';ctx.lineWidth=1;for(let i=0;i<128;i+=16){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,128);if(color==='#e5cf9f'){ctx.moveTo(0,i);ctx.lineTo(128,i);}ctx.stroke();}for(let i=0;i<35;i++){ctx.fillStyle='#e9ddb533';ctx.fillRect(i*47%128,i*71%128,2,2);}texture.update();m.diffuseTexture=texture;}materials.set(key,m);return m;};
 function mesh(type,name,opts,color,pos,parent=null,animated=false){const m=B.MeshBuilder[type](name,opts,scene);m.material=mat(color);m.position.set(...pos);if(parent)m.parent=parent;if(!parent&&!animated)staticMeshes.push(m);m.receiveShadows=true;if(!['cloud-sea','distant-cloud','dock-ring','high-wind-ring','window'].includes(name))r.shadows?.addShadowCaster(m);return m;}
 function loft(name,sections,color,parent=null){const vertices=[],indices=[],uvs=[],segments=14;sections.forEach((s,j)=>{for(let i=0;i<segments;i++){const a=i/segments*Math.PI*2;vertices.push(Math.cos(a)*s[1],Math.sin(a)*s[2]+(s[3]||0),s[0]);uvs.push(i/segments,j/(sections.length-1));if(j){const k=j*segments+i,prev=(i+1)%segments;indices.push(k,j*segments+prev,(j-1)*segments+i,j*segments+prev,(j-1)*segments+prev,(j-1)*segments+i);}}});const normals=[];B.VertexData.ComputeNormals(vertices,indices,normals);const v=new B.VertexData();Object.assign(v,{positions:vertices,indices,normals,uvs});const m=new B.Mesh(name,scene);v.applyToMesh(m);m.material=mat(color);m.parent=parent;if(!['cloud-sea','distant-cloud','dock-ring','high-wind-ring','window'].includes(name))r.shadows?.addShadowCaster(m);return m;}
 // Suspended sea, ridgelines and lantern harbors.
 const sea=mesh('CreateGround','cloud-sea',{width:150,height:150,subdivisions:1},'#142e45',[0,-5,0]);sea.material.alpha=.92;
 for(let i=0;i<4;i++){const h=HARBORS[i],root=new B.TransformNode('harbor-'+i,scene);root.position.set(h.x,0,h.z);const rock=loft('floating-cliff',[[ -3,.05,.05],[ -2,1.3,1.2],[-.5,2.7,2.6],[.5,2.4,2.3],[.6,.01,.01]],'#465d67',root);rock.rotation.x=-Math.PI/2;mesh('CreateCylinder','turf',{diameter:5,height:.35,tessellation:24},'#648a7c',[0,.6,0],root);mesh('CreateCylinder','landing-medallion',{diameter:3.3,height:.09,tessellation:32},i%2?'#d6a87e':'#7fc7bd',[0,.84,0],root);const ring=mesh('CreateTorus','dock-ring',{diameter:3,thickness:.06,tessellation:32},'#f5dca1',[0,.92,0],root);ring.rotation.x=0;
  for(let j=0;j<3;j++){const angle=j*2.1+i,x=Math.cos(angle)*2,z=Math.sin(angle)*2;mesh('CreateBox','timber-house',{width:.65,height:.85,depth:.75},'#8f7669',[x,1.2,z],root);const roof=mesh('CreateCylinder','copper-roof',{diameterTop:0,diameterBottom:1.15,height:.65,tessellation:4},'#b37e71',[x,1.9,z],root);roof.rotation.y=Math.PI/4;mesh('CreateBox','window',{width:.28,height:.32,depth:.03},'#f7d79b',[x,1.35,z-.39],root);mesh('CreateCylinder','lantern-pole',{diameter:.07,height:2.3,tessellation:6},'#344652',[x*.7,1.6,z*.7],root);mesh('CreateSphere','lantern',{diameter:.26,segments:8},'#edcb87',[x*.7,2.85,z*.7],root);}
  mesh('CreateBox','wooden-pier',{width:3.6,height:.15,depth:.5},'#b59b78',[0,.9,-2.6],root);for(let j=-2;j<=2;j++)mesh('CreateCylinder','pier-post',{diameter:.1,height:.8,tessellation:6},'#827365',[j*.7,.65,-2.65],root);
  const mast=mesh('CreateCylinder','signal-mast',{diameter:.1,height:4,tessellation:8},'#af9475',[2,2.6,0],root);const flag=loft('harbor-pennant',[[0,.01,.01],[.02,.6,.28],[.05,.01,.01]],i%2?'#be8fbc':'#7bc8c2',root);flag.position.set(2,4.2,0);flag.rotation.y=Math.PI/2;
 }
 for(const o of game.obstacles){const m=mesh('CreateCylinder','wind-carved-spire',{diameterTop:o.r*.6,diameterBottom:o.r*2,height:o.height,tessellation:7},'#506978',[o.x,o.height/2,o.z]);staticCollider(r,m);mesh('CreateTorus','spire-vine',{diameter:o.r*1.5,thickness:.18,tessellation:10},'#6f9483',[o.x,o.height*.6,o.z]);}
 // Batch static scenery by material; preserve independent collider meshes and moving craft.
 const batches=new Map();for(const m of [...scene.meshes])if(m.name!=='wind-carved-spire'&&m.getTotalVertices()){m.computeWorldMatrix(true);const list=batches.get(m.material)||[];list.push(m);batches.set(m.material,list);}for(const [material,parts]of batches)if(parts.length>1){for(const m of parts)r.shadows?.removeShadowCaster(m);const merged=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(merged){merged.name='batched-harbor-'+material.name;merged.material=material;merged.receiveShadows=true;r.shadows?.addShadowCaster(merged);}}
 // Original lofted biplane courier craft: hull, swept fabric wings, struts, pilot and spinning propeller.
 for(const p of game.players){const root=new B.TransformNode('courier-'+p.id,scene),color=p.id?'#e6ab84':'#7bd8cb';loft('enameled-gondola',[[-1.5,.03,.03],[-1,.25,.3],[0,.42,.4],[.8,.35,.33],[1.35,.03,.03]],color,root);for(const side of [-1,1]){const wing=loft('swept-canvas-wing',[[-.5,.02,.03],[-.25,2.2,.06],[.2,2.6,.06],[.5,.1,.03]],'#e5cf9f',root);wing.position.y=.5;wing.position.x=side*.15;wing.scaling.x=.75;wing.rotation.z=side*.06;for(const x of [-1.2,1.2]){const strut=mesh('CreateCylinder','wing-strut',{diameter:.045,height:.85,tessellation:5},'#766854',[x,.12,side*.25],root);strut.rotation.z=x*.25;}}
  const tail=loft('tail-fin',[[-1.6,.01,.01],[-1.35,.6,.2],[-1,.08,.03]],'#ab8d9d',root);tail.position.y=.15;mesh('CreateSphere','pilot-helmet',{diameter:.44,segments:12},'#655454',[0,.57,.1],root);mesh('CreateBox','pilot-goggles',{width:.38,height:.12,depth:.12},'#e7cb89',[0,.62,.3],root);for(const x of [-.1,.1])mesh('CreateSphere','glass-goggle',{diameter:.12,segments:8},'#88cfd6',[x,.63,.37],root);const prop=new B.TransformNode('propeller',scene);prop.parent=root;prop.position.z=1.4;for(let j=0;j<2;j++){const blade=mesh('CreateBox','prop-blade',{width:.1,height:1,depth:.05},'#7b6b5f',[0,0,0],prop);blade.rotation.z=j*Math.PI/2;}const parcel=mesh('CreateBox','parcel',{size:.45},'#d2b789',[0,-.46,-.2],root);mesh('CreateTorus','parcel-ribbon',{diameter:.52,thickness:.05,tessellation:12},'#9a727e',[0,0,0],parcel);const beacon=mesh('CreateTorus','courier-outline',{diameter:2.4,thickness:.045,tessellation:24},color,[0,-.75,0],root);pilots.push({root,prop,parcel,beacon});proxies.push(controlledCapsule(r,{name:'courier-body-'+p.id,height:1.2,radius:.5}));}
 for(const g of game.rings){const m=mesh('CreateTorus','high-wind-ring',{diameter:2.7,thickness:.1,tessellation:32},'#f0cf86',[g.x,g.y,g.z],null,true);m.rotation.x=Math.PI/2;rings.push(m);}
 for(let i=0;i<game.storms.length;i++){const root=new B.TransformNode('storm-front',scene);for(let j=0;j<5;j++){const m=mesh('CreateSphere','storm-puff',{diameter:1.4,segments:8},'#4d586f',[Math.sin(j*2)*.8,Math.cos(j)*.3,Math.cos(j*2)*.8],root);m.scaling.y=.6;}const parts=root.getChildMeshes();for(const m of parts)r.shadows?.removeShadowCaster(m);const merged=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(merged){merged.parent=root;r.shadows?.addShadowCaster(merged);}storms.push(root);}
 const targets=game.players.map((p,i)=>{const m=mesh('CreateTorus','delivery-marker',{diameter:4,thickness:.15,tessellation:32},i?'#e6ab84':'#8ee7d5',[0,1,0],null,true);m.material=mat(i?'#e6ab84':'#8ee7d5',.3);return m;});
 const clouds=[];for(let i=0;i<18;i++){const m=mesh('CreateSphere','distant-cloud',{diameter:4,segments:6},'#406276',[-32+(i%6)*13,-2+Math.sin(i)*.4,-24+Math.floor(i/6)*24],null,true);m.scaling.set(1.6,.25,.8);m.material.alpha=.35;clouds.push(m);}
 const effects=create3DEffects(r,{getPresentation});let aspect=0,overview=false;
 return{pilots,toggleCamera(){overview=!overview;aspect=0;return overview;},update(dt){const motion=getPresentation().reduceMotion?0:1;const a=r.canvas.clientWidth/Math.max(1,r.canvas.clientHeight);if(overview){r.camera.radius=Math.min(110,Math.max(34,34/Math.max(.42,a)));r.camera.target.set(0,2,0);}else{const mean=game.players.reduce((n,p)=>({x:n.x+p.x/game.players.length,y:n.y+p.y/game.players.length,z:n.z+p.z/game.players.length}),{x:0,y:0,z:0}),spread=Math.max(0,...game.players.map(p=>Math.hypot(p.x-mean.x,p.z-mean.z)));r.camera.radius=Math.min(100,(23+spread*1.2)/Math.min(1,Math.max(.5,a)));r.camera.target.set(mean.x,mean.y,mean.z);}aspect=a;for(const p of game.players){const v=pilots[p.id];v.root.position.set(p.x,p.y,p.z);v.root.rotation.set(p.vz*.016,p.angle,-p.vx*.025);v.prop.rotation.z+=dt*motion*(15+Math.hypot(p.vx,p.vz));v.parcel.setEnabled(p.carrying);v.root.scaling.setAll(p.shield&&Math.floor(game.clock*8)%2?.92:1);proxies[p.id].move(p.x,p.y,p.z);const h=HARBORS[game.job(p)[p.carrying?'destination':'source']];targets[p.id].position.set(h.x,1.05+Math.sin(game.clock*2)*.08,h.z);targets[p.id].setEnabled(p.delivered<game.goal);}storms.forEach((m,i)=>{const s=game.storm(i);m.position.set(s.x,5+Math.sin(game.clock+i)*.2,s.z);m.scaling.setAll(s.r);});rings.forEach(m=>m.rotation.y+=dt*.5*motion);clouds.forEach((m,i)=>{m.setEnabled(r.quality!=='low'||i<6);m.position.x+=dt*.15*motion;if(m.position.x>40)m.position.x=-40;});effects.update(dt);},event(e){effects.event({type:e.type==='bump'?'hit':'heal',point:{x:e.x,y:e.y,z:e.z}});},stats:()=>r.stats(),dispose(){effects.dispose();for(const p of proxies)p.dispose();}};
}
